/** Static type system for Elementum calculated expressions. */
import type { FieldRef } from "../../../catalog/types.js";
import type { AppField, AttachmentAppField, BooleanAppField, CalculationExpression, DateAppField, DateTimeAppField, DecimalAppField, FieldScope, GroupAppField, HandleAppField, HtmlAppField, JsonAppField, MultiPicklistAppField, NumberAppField, PicklistAppField, TextAppField, UserAppField } from "../../../core/types/app.js";
import type { Ref } from "../../shared/ref.js";
/** Exact Knowhere/Ultron scalar result families plus UUID's internal type. */
export type ExprType = "number" | "decimal" | "text" | "handle" | "html" | "bool" | "date" | "datetime" | "picklist" | "multiPicklist" | "user" | "group" | "attachment" | "json" | "uuid";
export type ExprCardinality = "single" | "multiple";
export type ExprContext = "standalone" | "record";
export type CalculationInclude = "auto" | "manual" | "both" | {
    readonly picklist: FieldRef<string, string, "PICKLIST">;
};
/** A calculation node's exact result family, cardinality, and context. */
export interface Expr<T extends ExprType, Cardinality extends ExprCardinality = "single", Context extends ExprContext = "standalone"> extends CalculationExpression {
    readonly __exprType: T;
    readonly __exprCardinality: Cardinality;
    readonly __exprContext: Context;
    /**
     * Set on comparison nodes (`a > b`, `a = b`, …). The platform grammar
     * parses those as a "boolean expression", a production a calculation's
     * root does not accept, so the root must be a function call.
     */
    readonly __exprBoolShape?: "comparison";
}
export type AnyExpr = Expr<ExprType, ExprCardinality, ExprContext>;
export type ScalarExpr<T extends ExprType = ExprType, Context extends ExprContext = ExprContext> = Expr<T, "single", Context>;
export type NumericExpr<Context extends ExprContext = ExprContext> = Expr<"number", "single", Context> | Expr<"decimal", "single", Context>;
export type ComparableExprType = "number" | "decimal" | "text" | "handle" | "html" | "date" | "datetime";
export type AppFieldOfExprType<T extends ExprType, Scope extends FieldScope = FieldScope> = T extends "number" ? NumberAppField<Scope> : T extends "decimal" ? DecimalAppField<Scope> : T extends "text" ? TextAppField<Scope> : T extends "handle" ? HandleAppField<Scope> : T extends "html" ? HtmlAppField<Scope> : T extends "bool" ? BooleanAppField<Scope> : T extends "date" ? DateAppField<Scope> : T extends "datetime" ? DateTimeAppField<Scope> : T extends "picklist" ? PicklistAppField<Scope> : T extends "multiPicklist" ? MultiPicklistAppField<Scope> : T extends "user" ? UserAppField<Scope> : T extends "group" ? GroupAppField<Scope> : T extends "attachment" ? AttachmentAppField<Scope> : T extends "json" ? JsonAppField<Scope> : never;
type FieldTypeForExprType<T extends ExprType> = T extends "number" ? "NUMBER" : T extends "decimal" ? "DECIMAL" : T extends "text" ? "TEXT" | "RICH_TEXT" : T extends "handle" ? "HANDLE" : T extends "html" ? "HTML" : T extends "bool" ? "BOOLEAN" : T extends "date" ? "DATE" : T extends "datetime" ? "DATETIME" : T extends "picklist" ? "PICKLIST" : T extends "multiPicklist" ? "MULTI_PICKLIST" : T extends "user" ? "USER" | "USER_ID" : T extends "group" ? "GROUP" | "GROUP_ID" : T extends "attachment" ? "ATTACHMENT" | "ATTACHMENT_ID" : T extends "json" ? "JSON" : never;
export type FieldRefOfExprType<T extends ExprType> = FieldRef<string, string, FieldTypeForExprType<T>>;
export type FieldRefExprType<F extends FieldRef> = F["fieldType"] extends "NUMBER" ? "number" : F["fieldType"] extends "DECIMAL" ? "decimal" : F["fieldType"] extends "BOOLEAN" ? "bool" : F["fieldType"] extends "DATE" ? "date" : F["fieldType"] extends "DATETIME" ? "datetime" : F["fieldType"] extends "PICKLIST" ? "picklist" : F["fieldType"] extends "MULTI_PICKLIST" ? "multiPicklist" : F["fieldType"] extends "USER" | "USER_ID" ? "user" : F["fieldType"] extends "GROUP" | "GROUP_ID" ? "group" : F["fieldType"] extends "ATTACHMENT" | "ATTACHMENT_ID" ? "attachment" : F["fieldType"] extends "JSON" ? "json" : F["fieldType"] extends "HANDLE" ? "handle" : F["fieldType"] extends "HTML" ? "html" : F["fieldType"] extends "TEXT" | "RICH_TEXT" ? "text" : ExprType;
export type LiteralOfExprType<T extends ExprType> = T extends "number" | "decimal" ? number : T extends "text" ? string : T extends "bool" ? boolean : never;
/** Inputs accepted by calc builders, including direct catalog/workflow refs. */
export type ExprLike<T extends ExprType> = ScalarExpr<T> | AppFieldOfExprType<T> | FieldRefOfExprType<T> | Ref<unknown, T> | LiteralOfExprType<T>;
export type NumericLike = ExprLike<"number"> | ExprLike<"decimal">;
export type BoolLike = ExprLike<"bool">;
export type AppFieldExprType<F extends AppField<FieldScope>> = F extends NumberAppField<FieldScope> ? "number" : F extends DecimalAppField<FieldScope> ? "decimal" : F extends TextAppField<FieldScope> ? "text" : F extends HandleAppField<FieldScope> ? "handle" : F extends HtmlAppField<FieldScope> ? "html" : F extends BooleanAppField<FieldScope> ? "bool" : F extends DateAppField<FieldScope> ? "date" : F extends DateTimeAppField<FieldScope> ? "datetime" : F extends PicklistAppField<FieldScope> ? "picklist" : F extends MultiPicklistAppField<FieldScope> ? "multiPicklist" : F extends UserAppField<FieldScope> ? "user" : F extends GroupAppField<FieldScope> ? "group" : F extends AttachmentAppField<FieldScope> ? "attachment" : F extends JsonAppField<FieldScope> ? "json" : never;
export type ExprTypeOf<Value> = Value extends Expr<infer T, ExprCardinality, ExprContext> ? T : Value extends FieldRef ? FieldRefExprType<Value> : Value extends Ref<unknown, infer T extends ExprType> ? T : Value extends AppField<FieldScope> ? AppFieldExprType<Value> : Value extends boolean ? "bool" : Value extends string ? "text" : Value extends number ? NumberLiteralExprType<Value> : never;
export type ExprContextOf<Value> = Value extends Expr<ExprType, ExprCardinality, infer Context> ? Context : Value extends FieldRef | AppField<FieldScope> ? "record" : "standalone";
export type MergeContext<A extends ExprContext, B extends ExprContext> = "record" extends A | B ? "record" : "standalone";
export type ContextOfValues<Values extends readonly unknown[]> = Values extends readonly [infer Head, ...infer Rest] ? MergeContext<ExprContextOf<Head>, ContextOfValues<Rest>> : "standalone";
export type ComposedExpr<T extends ExprType, Values extends readonly unknown[], Cardinality extends ExprCardinality = "single"> = Expr<T, Cardinality, ContextOfValues<Values>>;
export type NumberLiteralExprType<N extends number> = number extends N ? "number" | "decimal" : `${N}` extends `${string}.${string}` ? "decimal" : "number";
export type NumericExprTypeOf<Value> = Extract<ExprTypeOf<Value>, "number" | "decimal">;
export type NumericPromotion<A, B> = "decimal" extends NumericExprTypeOf<A> | NumericExprTypeOf<B> ? "decimal" : "number";
export type DateMathPromotion<A, B> = ExprTypeOf<A> extends "datetime" ? "datetime" : ExprTypeOf<A> extends "date" ? "decimal" extends NumericExprTypeOf<B> ? "datetime" : "date" : NumericPromotion<A, B>;
export {};
